begin;select plan(35);
select has_table('public','provider_asset_bindings','provider assets exist');select has_table('public','provider_asset_secrets','asset credentials are isolated');select has_table('public','provider_access_reviews','review readiness exists');select has_table('public','provider_verification_challenges','manual verification challenges exist');select has_table('public','meta_webhook_subscriptions','Meta webhook lifecycle exists');
select ok((select relforcerowsecurity from pg_class where oid='public.provider_asset_bindings'::regclass),'asset RLS forced');select ok((select relforcerowsecurity from pg_class where oid='public.provider_asset_secrets'::regclass),'secret RLS forced');select ok((select relforcerowsecurity from pg_class where oid='public.provider_access_reviews'::regclass),'review RLS forced');select ok((select relforcerowsecurity from pg_class where oid='public.provider_verification_challenges'::regclass),'challenge RLS forced');select ok((select relforcerowsecurity from pg_class where oid='public.meta_webhook_subscriptions'::regclass),'webhook RLS forced');
select table_privs_are('public','provider_asset_bindings','authenticated',array['SELECT'],'browser cannot mutate stable assets');select table_privs_are('public','provider_asset_secrets','authenticated',array[]::text[],'browser cannot read asset credentials');select table_privs_are('public','provider_access_reviews','authenticated',array['SELECT'],'browser cannot approve review state');select table_privs_are('public','provider_verification_challenges','authenticated',array['SELECT'],'browser cannot self verify');select table_privs_are('public','meta_webhook_subscriptions','authenticated',array['SELECT'],'browser cannot mutate webhook state');
select function_privs_are('public','select_provider_asset',array['uuid','text','text','text','text','text','text','text','jsonb'],'authenticated',array[]::text[],'asset selection is server-only');select function_privs_are('public','claim_expansion_two_connections',array['integer','uuid'],'authenticated',array[]::text[],'source claims are worker-only');select function_privs_are('public','claim_expansion_two_connections',array['integer','uuid'],'service_role',array['EXECUTE'],'worker may claim sources');
select col_is_pk('public','provider_asset_bindings','id','asset primary key');select col_is_pk('public','provider_access_reviews','id','review primary key');select col_has_check('public','provider_asset_bindings','asset_type','asset types constrained');select col_has_check('public','provider_access_reviews','status','review states constrained');select col_has_check('public','provider_verification_challenges','status','challenge state constrained');
select is(public.trust_provider_family('instagram'),'meta','Instagram is Meta family');select is(public.trust_provider_family('facebook'),'meta','Facebook is Meta family');select is(public.trust_provider_family('tiktok'),'bytedance','TikTok is ByteDance family');
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,recovery_token,email_change_token_new,email_change)values('00000000-0000-0000-0000-000000000000','83000000-0000-4000-8000-000000000001','authenticated','authenticated','stage83@example.com',crypt('pw',gen_salt('bf')),now(),'{}','{}',now(),now(),'','','','');
update public.creators set display_name='Stage 8.3',public_slug='stage-83'where owner_user_id='83000000-0000-4000-8000-000000000001';
insert into public.connected_accounts(id,creator_id,platform,account_type,label,url,is_public,external_account_id,external_account_name,external_account_url,provider_status,connection_health,watch_enabled,auto_create_drafts,auto_send)select'83000000-0000-4000-8000-000000000010',id,'facebook','official','Page','https://facebook.com/stage83',true,'page-83','Page','https://facebook.com/stage83','ready','healthy',true,true,false from public.creators where public_slug='stage-83';
set local role service_role;select set_config('request.jwt.claim.role','service_role',true);
select lives_ok($$select public.select_provider_asset('83000000-0000-4000-8000-000000000010','facebook','facebook_page','page-83','','Stage Page','stage83','https://facebook.com/stage83','{"authority":true}')$$,'service selects an authorized Page');select is((select count(*)::integer from public.provider_asset_bindings),1,'one selected asset');select is((select count(*)::integer from public.provider_content_sources where provider='facebook'),1,'selection creates one source');select is((select approval_required from public.provider_asset_bindings),true,'approval required by default');select is((select public_visible from public.provider_asset_bindings),true,'verified selected asset may be public');
select throws_ok($$select public.select_provider_asset('83000000-0000-4000-8000-000000000010','facebook','facebook_page','page-other','','Conflict','other','https://facebook.com/other','{}')$$,'23505',null,'stable connection ID mismatch is protected');
reset role;select is((select count(*)::integer from public.creator_emergencies),0,'asset selection does not activate emergency');select is((select count(*)::integer from public.update_deliveries),0,'asset selection does not queue delivery');select is((select count(*)::integer from public.provider_access_reviews where status='approved'),0,'review never defaults approved');
select*from finish();rollback;
